CREATE TABLE IF NOT EXISTS "mes_pro_process" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "product_name" varchar(128) DEFAULT NULL,
    "code" varchar(64) DEFAULT NULL,
    "name" varchar(255) DEFAULT NULL,
    "attention" varchar(500) DEFAULT NULL,
    "sop_file_url" varchar(2048) DEFAULT NULL,
    "status" int DEFAULT NULL,
    "manual_shift_capacity" decimal(18,6) DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "mes_dv_machinery" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(64) DEFAULT NULL,
    "name" varchar(255) DEFAULT NULL,
    "brand" varchar(128) DEFAULT NULL,
    "specification" varchar(255) DEFAULT NULL,
    "machinery_type_id" bigint DEFAULT NULL,
    "workshop_id" bigint DEFAULT NULL,
    "process_name" varchar(255) DEFAULT NULL,
    "standard_hourly_capacity" decimal(18,6) DEFAULT NULL,
    "status" tinyint DEFAULT NULL,
    "last_mainten_time" timestamp DEFAULT NULL,
    "last_check_time" timestamp DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "mes_dv_machinery_process" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "machinery_id" bigint DEFAULT NULL,
    "process_id" bigint DEFAULT NULL,
    "process_code" varchar(64) DEFAULT NULL,
    "machinery_code" varchar(64) DEFAULT NULL,
    "line_name" varchar(255) DEFAULT NULL,
    "process_name" varchar(255) DEFAULT NULL,
    "device_name" varchar(255) DEFAULT NULL,
    "device_quantity" decimal(18,6) DEFAULT NULL,
    "ten_half_hour_daily_capacity" decimal(18,6) DEFAULT NULL,
    "standard_hourly_capacity" decimal(18,6) DEFAULT NULL,
    "source_row_no" int DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "mes_dv_machinery_type" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(64) DEFAULT NULL,
    "name" varchar(255) DEFAULT NULL,
    "parent_id" bigint DEFAULT 0,
    "status" tinyint DEFAULT NULL,
    "sort" int DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "mes_md_workshop" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(64) DEFAULT NULL,
    "name" varchar(255) DEFAULT NULL,
    "area" decimal(18,6) DEFAULT NULL,
    "charge_user_id" bigint DEFAULT NULL,
    "status" tinyint DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "mes_pro_process" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "product_name" varchar(128) DEFAULT NULL,
    "code" varchar(64) DEFAULT NULL,
    "name" varchar(255) DEFAULT NULL,
    "attention" varchar(1000) DEFAULT NULL,
    "sop_file_url" varchar(2048) DEFAULT NULL,
    "status" tinyint DEFAULT NULL,
    "manual_shift_capacity" decimal(18,6) DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);
